namespace Healthcare.Tests.Catalog;

using FluentAssertions;
using Healthcare.Modules.Catalog.Domain;
using Healthcare.SharedKernel;
using Xunit;

/// <summary>
/// SKU creation and code generation.
///
/// The code is generated by an injected function, so these tests are
/// deterministic without depending on the production generator's alphabet.
/// </summary>
public sealed class SkuTests
{
    private static readonly DateTimeOffset Now = new(2026, 10, 3, 12, 0, 0, TimeSpan.Zero);

    private static readonly Guid ProductId = Guid.NewGuid();

    private static Result<Sku> Create(string? variant = null, string code = "SKU-TEST0001") =>
        Sku.Create(ProductId, variant, Now, () => code);

    [Fact]
    public void A_sku_is_created_with_the_supplied_code()
    {
        var sku = Create().Value;

        sku.Code.Should().Be("SKU-TEST0001");
        sku.ProductId.Should().Be(ProductId);
        sku.IsActive.Should().BeTrue();
    }

    [Fact]
    public void The_code_is_normalised_to_uppercase()
    {
        var sku = Create(code: "sku-test0001").Value;

        sku.Code.Should().Be("SKU-TEST0001");
    }

    [Fact]
    public void An_empty_code_is_rejected()
    {
        var result = Create(code: "   ");

        result.IsFailure.Should().BeTrue();
        result.ErrorCode.Should().Be("sku_code_required");
    }

    [Fact]
    public void A_code_longer_than_64_characters_is_rejected()
    {
        var result = Create(code: new string('A', 65));

        result.ErrorCode.Should().Be("sku_code_too_long");
    }

    [Fact]
    public void A_missing_product_is_rejected()
    {
        var result = Sku.Create(Guid.Empty, null, Now, () => "SKU-TEST0001");

        result.ErrorCode.Should().Be("sku_product_required");
    }

    [Fact]
    public void A_missing_code_generator_throws_rather_than_returning_a_result()
    {
        // The domain does not generate codes itself: the scheme is a deployment
        // concern. A caller that supplies none has made a wiring mistake, and
        // no caller has a sensible recovery for that — so it throws rather
        // than returning a Result that reads like a business outcome.
        var act = () => Sku.Create(ProductId, null, Now, codeGenerator: null!);

        act.Should().Throw<InvalidOperationException>()
            .WithMessage("*code generator*");
    }

    [Fact]
    public void A_variant_description_is_stored_when_supplied()
    {
        var sku = Create(variant: "نوار بازو ۲۲ تا ۳۲ سانتی‌متر").Value;

        sku.VariantDescription.Should().Be("نوار بازو ۲۲ تا ۳۲ سانتی‌متر");
    }

    [Fact]
    public void A_blank_variant_description_becomes_null()
    {
        // Null means "no variant", which is different from an empty string a
        // caller might have intended as a placeholder.
        var sku = Create(variant: "   ").Value;

        sku.VariantDescription.Should().BeNull();
    }

    [Fact]
    public void A_variant_description_longer_than_300_characters_is_rejected()
    {
        var result = Create(variant: new string('ن', 301));

        result.ErrorCode.Should().Be("sku_variant_too_long");
    }

    [Fact]
    public void Update_variant_replaces_the_description()
    {
        var sku = Create(variant: "قدیمی").Value;

        sku.UpdateVariant("جدید", Now);

        sku.VariantDescription.Should().Be("جدید");
        sku.UpdatedAt.Should().Be(Now);
    }

    [Fact]
    public void Update_variant_accepts_null()
    {
        var sku = Create(variant: "قدیمی").Value;

        sku.UpdateVariant(null, Now);

        sku.VariantDescription.Should().BeNull();
    }

    [Fact]
    public void Deactivation_is_available()
    {
        var sku = Create().Value;

        sku.Deactivate(Now);

        sku.IsActive.Should().BeFalse();
    }

    [Fact]
    public void Reactivation_is_available()
    {
        var sku = Create().Value;

        sku.Deactivate(Now);
        sku.Reactivate(Now);

        sku.IsActive.Should().BeTrue();
    }

    [Fact]
    public void A_failed_result_cannot_yield_a_value()
    {
        var result = Create(code: "");

        var act = () => result.Value;

        act.Should().Throw<InvalidOperationException>();
    }
}
